import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

describe("Game of Life - Next Generation", () => {
  it.todo("returns an empty grid for an empty grid — [] → []");
  it.todo("kills a single lonely cell — [(0,0)] → []");
  it.todo(
    "Rule 1 Underpopulation: kills two adjacent cells with 1 neighbor each — [(0,1), (1,1)] → []",
  );
  it.todo(
    "Rule 2 Survival: a live cell with 3 live neighbors lives on — [(0,0), (1,0), (2,0), (1,2)] keeps (1,1)... center (1,1) survives",
  );
  it.todo(
    "Rule 3 Overpopulation: a live cell with 4 live neighbors dies — center (1,1) absent from next generation",
  );
  it.todo(
    "Rule 4 Reproduction: a dead cell with exactly 3 live neighbors becomes alive — [(0,0), (1,0), (0,1)] → includes (1,1)",
  );
  it.todo(
    "handles negative coordinates — a lonely cell at (-5,-7) dies, [(-5,-7)] → []",
  );
  it.todo(
    "Block still life stays unchanged — [(0,0), (1,0), (0,1), (1,1)] → same 4 cells",
  );
  it.todo(
    "Blinker oscillates from vertical to horizontal — [(0,0), (0,1), (0,2)] → [(-1,1), (0,1), (1,1)]",
  );
  it.todo(
    "Blinker oscillates back to vertical after two generations — [(-1,1), (0,1), (1,1)] → [(0,0), (0,1), (0,2)]",
  );
});

