const SMALLEST_SURVIVING_POPULATION = 3;

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const everyCellDies = liveCells.length < SMALLEST_SURVIVING_POPULATION;
  if (everyCellDies) return [];

  // Fake: hardcoded to satisfy the single Rule 2 Survival example.
  return [[1, 1]];
}

input.new_string:
function countLiveNeighbors(cell: Cell, liveCells: Cell[]): number {
  const [x, y] = cell;
  return liveCells.filter(
    ([otherX, otherY]) =>
      !(otherX === x && otherY === y) &&
      Math.abs(otherX - x) <= 1 &&
      Math.abs(otherY - y) <= 1,
  ).length;
}

export function nextGeneration(liveCells: Cell[]): Cell[] {
  return liveCells.filter((cell) => {
    const neighbors = countLiveNeighbors(cell, liveCells);
    return neighbors === 2 || neighbors === 3;
  });
}

